    function whaleCall(){sound(118,2.8,'sine',.2);setTimeout(()=>sound(84,2.3,'sine',.13),520)}
    const rabbitPath=[[12,0,-23],[7,0,-14],[1,0,-5],[-8,0,2],[-18,0,6],[-27.3,0,8.2]].map(p=>new THREE.Vector3(...p));
    function triggerMidnight(){midnightRoomOpen=true;rabbitWaypoint=1;rabbit.position.copy(rabbitPath[0]);rabbit.visible=true;rabbitActive=true;midnightDoor.visible=true;showNotice('Midnight. Twelve chimes answer from inside the walls. A white rabbit crosses the library.',7);for(let i=0;i<12;i++)setTimeout(()=>sound(i===11?196:146,.75,'sine',.1),i*310)}
    function triggerBookEasterEgg(book){if(book.id===2701){whiteVolumeLevel=Math.min(3,whiteVolumeLevel+1);whaleCall();showNotice(whiteVolumeLevel<3?'A distant whale calls beyond the rain. Somewhere, a white volume climbs to a higher shelf.':'A distant whale calls beyond the rain. The white volume has reached the highest shelf.',6)}else if(book.id===5200){insectQueued=true;sound(62,.55,'sawtooth',.08)}else if(book.id===11&&midnightRoomOpen&&!awakenedBooks.has(11))showNotice('The little door seems to be listening as you begin Alice’s story.',5)}
    function usefulClue(){if(!awakenedBooks.has(11))return 'Useful thing: turn at least one page of Alice’s Adventures in Wonderland before midnight.';if(!discovered.has('west-shelf'))return 'Useful thing: one western shelf holds a book that sits askew and leans toward your hand.';if(!discovered.has('below-catalogue'))return 'Useful thing: the iron outline beside the fireplace is a hatch, not decoration.';if(!discovered.has('roof-book'))return 'Useful thing: the upper stair continues beyond the balcony and into the rain.';if(!discovered.has('tunnel'))return 'Useful thing: in the secret western room, listen for the wall that breathes.';return 'Useful thing: the telescope counts every different book whose pages you have turned.'}
    function showNotice(t,seconds=3){if(showNotice.gate&&!showNotice.gate())return;const inMainLibrary=player.pos.y>-.5&&Math.abs(player.pos.x)<57&&player.pos.z>-32&&player.pos.z<32;if(/Quill/i.test(t)&&!inMainLibrary)return;ui.notice.textContent=t;ui.notice.style.opacity=1;noticeTimer=seconds}
    const COLLECTION_NAMES={'brass-token':'Serendipity token','map-fragment':'Three-title map','silver-key':'Archive key','reader-ribbon':'Crimson reading ribbon','pressed-flower':'Pressed night flower','midnight-ink':'Bottle of midnight ink','last-catalogue':'The final catalogue'};
    function mysteryCount(){return MYSTERIES.filter(([id])=>discovered.has(id)).length}
    function updateSecretCount(){const count=mysteryCount();$('#secretCount').textContent=`${count} / ${SECRET_TOTAL}`}
    function updateCollectionDisplay(){deskToken.visible=collection.has('brass-token');deskMap.visible=collection.has('map-fragment');deskKey.visible=collection.has('silver-key')}
    function addCollection(id,message=''){if(collection.has(id))return false;collection.add(id);localStorage.setItem('athenaeum-collection',JSON.stringify([...collection]));updateCollectionDisplay();renderJournal();if(message)showNotice(message,5);return true}
    function currentJournalClue(){const count=mysteryCount();if(count===0)return 'Begin with the folded note on the central reading table. The dust around it has recently moved.';if(!collection.has('map-fragment'))return 'Three nearby titles whisper a direction: a whale, a rabbit, then pride. Take those books down in that order.';if(awakenedBooks.size<3)return 'The library changes when it is read. Turn pages in several different books and watch the central light.';if(!discovered.has('roof-book'))return 'The upper balcony stair continues past the old roofline. Look behind the bench where the rain cannot quite reach.';if(count<6)return 'The cat knows the public rooms. Listen when it stops and looks back.';if(!discovered.has('tunnel'))return 'Cold air escapes from the west. Not every wall beyond the false shelf is solid.';if(!discovered.has('below-catalogue'))return 'Near the fireplace, Quill avoids an iron outline in the floor.';if(!discovered.has('redacted-catalogue'))return 'Below the library, an abandoned desk keeps a catalogue whose missing words are darker than ink.';return 'Every recorded path is awake. Follow the tunnel beyond the breathing wall.'}
    function renderJournalMap(){renderLibraryAtlas?.()}
    function renderJournal(){const count=mysteryCount(),keepsakes=[...collection].map(id=>COLLECTION_NAMES[id]).filter(Boolean);$('#journalProgress').textContent=`${count} of ${SECRET_TOTAL} mysteries recorded`;$('#mysteryList').innerHTML=MYSTERIES.map(([id,name],i)=>discovered.has(id)?`<div class="mystery-entry">${i+1}. ${name}</div>`:`<div class="mystery-entry locked">${i+1}. An unrecorded whisper</div>`).join('');$('#collectionList').innerHTML=keepsakes.length?keepsakes.map(name=>`<span class="collection-chip">${name}</span>`).join(''):'<span class="mystery-entry locked">The desk is waiting.</span>';const records=$('#roomRecords');records.replaceChildren();for(const [id,record] of Object.entries(ROOM_RECORDS)){const entry=document.createElement('div');entry.className=roomRecords.has(id)?'mystery-entry':'mystery-entry locked';if(roomRecords.has(id)){const title=document.createElement('strong'),story=document.createElement('p');title.textContent=record.title;story.textContent=record.text;entry.append(title,story)}else entry.textContent='A reason not yet found';records.append(entry)}renderJournalMap();renderDiscoveryStats?.();$('#journalClue').textContent=currentJournalClue()}
    function readRoomRecord(id){const record=ROOM_RECORDS[id];if(!record)return;if(!roomRecords.has(id)){roomRecords.add(id);localStorage.setItem('athenaeum-room-records',JSON.stringify([...roomRecords]));renderJournal()}showNotice(`${record.title} — ${record.text} (Recorded in your hidden catalogue.)`,12);sound(520,.45,'triangle',.08)}
    function openJournal(){renderJournal();ui.pause.classList.add('hidden');ui.journal.classList.remove('hidden');document.exitPointerLock?.()}
    function closeJournal(){ui.journal.classList.add('hidden');if(started)requestLookLock()}
    function checkCentralMystery(silent=false){if(mysteryCount()<SECRET_TOTAL||finalDoorOpen>0)return;finalDoorOpen=.01;addCollection('silver-key');if(!silent)setTimeout(()=>showNotice('Every hidden path answers at once. A final door opens beyond the tunnel.',6),900)}
    function discoverSecret(id,message){if(!id||discovered.has(id))return false;window.libraryAnalytics?.track('Secret Discovered',{secret:id});discovered.add(id);localStorage.setItem('athenaeum-mysteries',JSON.stringify([...discovered]));lastDiscoveryAt=performance.now();updateSecretCount();renderJournal();sound(720,.55,'triangle',.12);showNotice(`${message}  Mystery ${mysteryCount()} of ${SECRET_TOTAL}.`,5);checkCentralMystery();return true}
    function recordReading(book){const memoryRoom=memoryZoneAt(player.pos.x,player.pos.z);if(memoryRoom)restoreMemoryRoom(memoryRoom.key,book);lastReadCategory=book.category;if(awakenedBooks.has(book.id))return;awakenedBooks.add(book.id);localStorage.setItem('athenaeum-awakened-books',JSON.stringify([...awakenedBooks]));readerStarGeometry.setDrawRange(0,Math.min(awakenedBooks.size,books.length));lastDiscoveryAt=performance.now();if(book.id===11){midnightDoorSlab.userData.title='The grown rabbit door';midnightDoorSlab.userData.author='A few pages of Alice have made it larger than an ordinary door.';midnightDoorSlab.userData.action='ENTER';showNotice('The tiny rabbit door stretches upward with a wooden sigh. Beyond its keyhole, shelves rise into darkness.',7)}else if(awakenedBooks.size>1)showNotice('A new star joins the reader’s constellation above the roof garden.',4);if(awakenedBooks.size===1)addCollection('reader-ribbon','A crimson reading ribbon appears on the central reading desk.');else if(awakenedBooks.size===3)addCollection('pressed-flower','Three books have stirred the library. A dark flower unfolds on the desk.');else if(awakenedBooks.size===5)addCollection('midnight-ink','The central lamp brightens. A bottle of midnight ink waits below it.');renderJournal();refreshReadingStack()}
    function recordBookSequence(book){pullSequence.push(book.id);while(pullSequence.length>3)pullSequence.shift();if(pullSequence.join(',')==='2701,11,1342')addCollection('map-fragment','Moby-Dick, Alice, Pride. Their initials unfold into a map on the reading desk.')}
    function recommendBook(){const unread=books.filter(b=>b.progress<.04);let pool=unread.length?unread:books;if(player.pos.x>37){const contested=pool.filter(b=>b.category==='Contested');if(contested.length)pool=contested}else if(weather==='STORM'){const storm=pool.filter(b=>b.category==='Gothic'||b.category==='Uncanny'||b.category==='Ghosts');if(storm.length)pool=storm}else if(lastReadCategory){const echoes=pool.filter(b=>b.category===lastReadCategory);if(echoes.length)pool=echoes}const quieter=pool.filter(b=>b.fame<90),choice=(quieter.length?quieter:pool)[Math.floor(Math.random()*(quieter.length?quieter.length:pool.length))],reasons={Contested:['It has survived attempts to silence the questions it asks.','Someone, at some point, wanted this book unavailable. It remains available.'],Gothic:['The weather has chosen something with a locked door in it.','This one prefers to be read after the lamps are low.'],Uncanny:['It will make the familiar room feel newly strange.','Nothing in it is impossible, which is exactly the trouble.'],Poetry:['The library thinks you have been listening between sentences.','This one rewards reading slowly, and rereading the same line twice.'],Philosophy:['This one rewards a reader willing to argue in the margins.','It will not tell you what to think, only make you do it.'],Adventure:['You have stood still long enough; this book will travel for you.','It does not stay in one place for very long, and neither will you.'],Society:['Its sharpest mysteries are hidden in ordinary rooms.','It watches a drawing room the way a detective watches a crime scene.'],'Returning Voices':['It was nearly forgotten, and it has things to say about that.','This one has come back into fashion exactly once before, and outlasted the fashion.'],'Almost Unread':['Almost no one has opened this in a very long time. You would be the exception.','Its pages are stiff from disuse, not age. Someone should fix that.'],Archive:['This one exists mostly to be kept, not read. Read it anyway.','It has spent more time being catalogued than being opened.'],Mystery:['It keeps its answer until the last page, and even then, barely.','Something in it does not add up, and that is rather the point.'],Wonder:['It asks you to believe something impossible, briefly, and see what happens.','This one was built to make the ordinary look unfamiliar again.'],'Fading Supernatural':['Whatever haunts this book is losing its grip on being believed.','It is the kind of ghost story that no longer quite frightens anyone, and is sadder for it.'],Memory:['It remembers things more clearly than the people in it do.','This one is less about what happened than about what refuses to be forgotten.'],Speculative:['It wonders what would happen if one thing were different, and follows through.','This one built a whole world out of a single “what if.”'],Satire:['It is laughing at something you will recognize immediately.','This one aims its wit at people who never saw it coming.'],Legend:['It has been told and retold long enough to stop needing to be true.','This one predates the idea of an original version.'],Epic:['It takes its time, and asks you to do the same.','This one was built to be read at length, not in passing.'],Drama:['Something in it is about to go wrong for someone, on purpose.','This one was built for a stage, even lying flat on a shelf.'],Sea:['It smells faintly of salt, or you imagine it does.','This one does not stay in sight of land for long.'],History:['It happened, mostly, and the parts that didn’t are the interesting ones.','This one remembers events more honestly than the people who lived them.'],Strange:['Nothing about it behaves quite the way you’d expect.','This one does not explain itself, and is better for it.'],Conscience:['It asks a question you would rather not have to answer.','This one was written by someone arguing with themselves.'],'Fading Speculative':['Its future is now somebody’s past, and it shows.','This one imagined a tomorrow that quietly stopped arriving.'],Modern:['It is newer than most of what surrounds it on these shelves.','This one hasn’t yet decided what era it belongs to.'],Ghosts:['Something in it has not finished leaving.','This one keeps a door open that most books would close.'],Journey:['It goes somewhere, and takes the long way there on purpose.','This one measures itself in miles, not chapters.'],Customs:['It notices the rules everyone else stopped seeing.','This one is more interested in table manners than in plot.'],Comedy:['It is trying, quite hard, to make you laugh, and it earns it.','This one does not take itself half as seriously as its neighbours do.'],'Fading Adventure':['Its excitement has mellowed into something closer to nostalgia.','This one used to move faster; it has earned the right to slow down.']},genericReasons=['It has been waiting for precisely this kind of visit.','The librarian has her reasons, even for the books she doesn’t explain.','Some recommendations don’t need a reason. This is one of them.'],reasonPool=reasons[choice.category],reason=reasonPool?reasonPool[Math.floor(Math.random()*reasonPool.length)]:genericReasons[Math.floor(Math.random()*genericReasons.length)];showNotice(`The librarian recommends “${choice.title}” by ${choice.author}. ${reason}`,8);librarianPause=9;sound(360,.45,'triangle',.1)}
    function guideCat(explicit=false){const next=MYSTERIES.find(([id])=>!discovered.has(id));if(!next){catGuideLabel='the tunnel wall';catGuideTarget=new THREE.Vector3(-51,0,-3);showNotice('Quill trots toward the tunnel, stopping often to make sure you follow.',5);return}const guides={'folded-note':[1,0,4],'book-under-table':[0,0,4],'book-mantel':[-13,0,-26],'book-balcony':[15,0,7],'roof-book':[15,0,27],'west-shelf':[-35,0,-3],'portrait-passage':[15,0,7],'unlabelled-orb':[-36,0,-3],'tunnel':[-50,0,-3],'below-catalogue':[-7,0,-25.8],'redacted-catalogue':[-7,0,-25.8]},words={'folded-note':['the central reading table','Quill trots toward the reading table, then looks back.'],'book-under-table':['the table’s shadow','A black tail slips beneath the central table, slowly enough to follow.'],'book-mantel':['the fireplace','Quill sets off for the fireplace, glancing over one shoulder.'],'book-balcony':['the eastern stair','Quill pads to the stair and looks deliberately upward.'],'roof-book':['the upper stair','Quill waits at the stair that rises beyond the roofline.'],'west-shelf':['the western shelves','Quill trots west and scratches once at a particular run of shelves.'],'portrait-passage':['the upper portrait','Quill leads toward the upper floor, then fixes on a portrait.'],'unlabelled-orb':['the false western shelf','Quill will not enter the hidden room, but leads you to its door.'],'tunnel':['the far stone wall','Quill presses onward toward the far wall of the secret library.'],'below-catalogue':['the iron floor outline','Quill leads to an iron outline near the fireplace.'],'redacted-catalogue':['the open hatch','Quill approaches the hatch, arches, and refuses to descend.']};const p=guides[next[0]],direction=words[next[0]];catGuideLabel=direction[0];catGuideTarget=new THREE.Vector3(p[0],p[1],p[2]);catPause=0;showNotice(direction[1],explicit?6:5);lastHintAt=performance.now()}
    function triggerAmbientEvent(){nextAmbientAt=performance.now()+50000+Math.random()*50000;const pick=a=>a[Math.floor(Math.random()*a.length)];if(player.pos.y<0){const whispers=['The furnace whispers a sentence from a book you have not opened.','Water strikes the brass bowls in the pattern of a name.','A chain tightens around the glass cabinet by itself.','Upstairs, Quill scratches once at the closed hatch.','A draft moves through the room with no open window to explain it.','Something shifts behind the brick, settling, or listening.','The pipes groan a note that almost resolves into a word.','A single footstep sounds on the stair above you, and does not repeat.','The bare bulb flickers in time with nothing you can hear.','Down here, the quiet has a weight to it that the upstairs quiet does not.'];showNotice(pick(whispers),5);sound(72,.9,'triangle',.1);return}const event=Math.floor(Math.random()*5);if(event===0&&!wanderingBook.visible){const places=[[7,1.05,9],[-24,1.05,6],[25,1.05,-10],[9,5.55,27],[-4,10.45,56]],p=places[Math.floor(Math.random()*places.length)];wanderingBook.position.set(p[0],p[1],p[2]);wanderingBook.userData.home.position.copy(wanderingBook.position);wanderingBook.visible=true;showNotice('A book falls open somewhere beyond sight.',5);sound(180,.5,'triangle',.12)}else if(event===1){showNotice(pick(['Footsteps cross the upper floor, one pace ahead of yours.','Someone walks the corridor above, matching your stride exactly.','A tread crosses the ceiling, then stops directly overhead.','Boots cross bare floorboards somewhere you have not yet explored.']),4);sound(68,.8,'sine',.1)}else if(event===2){showNotice(weather==='STORM'?pick(['Lightning reveals a figure in the eastern portrait.','A flash of lightning catches something moving where nothing should be.','Thunder rattles the windows hard enough to shift a book from its shelf.']):pick(['A chair creaks in an empty reading room.','Somewhere a page turns itself over in a room with no reader.','A reading room settles into silence a beat too suddenly.']),4)}else if(event===3){secretPortrait.group.rotation.z=.025;showNotice(pick(['One of the portraits is no longer hanging straight.','A portrait’s eyes seem to have shifted toward the door.','The frame of the eastern portrait ticks, faintly, like a cooling engine.','A portrait you passed earlier is now facing the wrong way.']),4)}else{showNotice(player.pos.y>9?pick(['The wind chimes answer a question you did not ask.','A gust finds the chimes and plays a tune no one composed.','The rooftop air carries a smell of rain that hasn’t started yet.']):pick(['A cool roof-garden breeze finds its way between the shelves.','A green smell drifts down from the roof garden, out of season.','Something like garden air moves through the stacks, out of place indoors.']),5);sound(440,.5,'triangle',.08)}}
