    function pullMachine(d){if(leverTime>0)return;noisyAction();leverTime=1.35;machinePulls++;localStorage.setItem('athenaeum-machine-pulls',machinePulls);d.trayGlow.intensity=18;if(!playSample('machineFlap',1,.98+Math.random()*.04))sound(95,.7,'square',.18);const unread=books.filter(b=>b.progress<.03);let pool=unread.length?unread:books;if(weather==='STORM'){const stormPool=pool.filter(b=>b.category==='Gothic'||b.category==='Uncanny');if(stormPool.length)pool=stormPool}else if(lastReadCategory&&machinePulls%2===0){const echoes=pool.filter(b=>b.category===lastReadCategory);if(echoes.length)pool=echoes}let best=pool[Math.floor(Math.random()*pool.length)];for(let i=0;i<6;i++){const candidate=pool[Math.floor(Math.random()*pool.length)];if(candidate.fame<best.fame)best=candidate}best.machineNote=weather==='STORM'?'Chosen while lightning stood at the windows.':lastReadCategory&&best.category===lastReadCategory?`The machine remembers your interest in ${lastReadCategory.toLowerCase()}.`:'The machine insists this book was waiting for you.';const tokenDue=machinePulls%3===0&&!collection.has('brass-token');showNotice('Gears turn. The empty tray begins to glow…',2.5);setTimeout(()=>{createMachineBook(best);if(tokenDue)addCollection('brass-token');showNotice(tokenDue?`${best.title} appears beside a newly minted brass token.`:`${best.title} waits in the brass tray.`,5)},1300)}

