    function readerLayout(){const page=$('.page.left'),style=getComputedStyle(page),font=parseFloat(style.fontSize)||readerSize,lineHeight=parseFloat(style.lineHeight)||font*1.58,padX=(parseFloat(style.paddingLeft)||0)+(parseFloat(style.paddingRight)||0),padY=(parseFloat(style.paddingTop)||0)+(parseFloat(style.paddingBottom)||0),chapter=$('#chapter'),chapterHeight=(chapter?.offsetHeight||19)+16,width=Math.max(220,(page.clientWidth||780)-padX),height=Math.max(lineHeight*8,(page.clientHeight||560)-padY-chapterHeight),canvas=readerLayout.canvas||(readerLayout.canvas=document.createElement('canvas')),ctx=canvas.getContext('2d');ctx.font=`${style.fontWeight} ${font}px ${style.fontFamily}`;return{ctx,width,maxLines:Math.max(8,Math.floor(height/lineHeight))}}
