    async function openReader(){if(!selected)return;const book=selected.userData.book,source=$('#readerSource'),listen=$('#listenBook');window.libraryAnalytics?.track('Book Opened',{book:book.id});readingStarted=false;triggerBookEasterEgg(book);ui.actions.classList.add('hidden');ui.reader.classList.remove('hidden');document.exitPointerLock?.();$('#readerTitle').textContent=book.title;$('#readerAuthor').textContent=book.author;if(book.sourceUrl){source.textContent=`${book.source||'Source'} · ${book.licence||'edition record'}`;source.href=book.sourceUrl;source.classList.remove('hidden')}else source.classList.add('hidden');/* Books with a LibriVox recording can be read aloud here, never by sending the reader away. */if(audiobooks?.available(book)){lastListenable=book;listen.textContent=audiobooks.label(book);listen.classList.remove('hidden')}else listen.classList.add('hidden');await loadBook(book);if(selected?.userData.book===book&&!ui.reader.classList.contains('hidden')){renderReader(book);readerOpenedAt=performance.now();scheduleReaderAside();scheduleAmbientRustle()}}
