    let pageTurnAnimTimer=null;
    function triggerPageTurnAnim(n){const el=$('.pages');if(!el)return;el.classList.remove('turn-next','turn-prev');void el.offsetWidth;el.classList.add(n>0?'turn-next':'turn-prev');clearTimeout(pageTurnAnimTimer);pageTurnAnimTimer=setTimeout(()=>el.classList.remove('turn-next','turn-prev'),340)}
