    const marginaliaSeen=new Set();
    const quillAsides=['Something warm settles against your foot. Quill has decided to stay for this chapter.','A soft weight leans into your ankle. Quill, apparently, approves of this book.','Quill’s tail flicks once against the chair leg, then goes still.','A quiet purr starts somewhere near the floor and does not stop.','Quill climbs into your lap without asking permission, as usual.','A whiskered face appears at the edge of the page, unimpressed by your pace.','Quill kneads the arm of the chair twice, then curls into a comma beside you.','One green eye opens, considers the room, and closes again.','Quill has claimed the warmest corner of the blanket and, by extension, you.','A small weight shifts against your side each time you turn a page.'];
    const timeAsides=['Somewhere in the library, a clock strikes an hour you did not notice passing.','You have been sitting here longer than you think.','The lamp beside you has burned lower without your noticing.','The room outside these pages has gone quieter than when you sat down.','The candle has guttered down by an inch since you last looked up.','Your tea, if you poured any, has long since gone cold.','The window has darkened a shade further while you weren’t watching it.','You reach the bottom of the page and find you cannot recall climbing it.','Somewhere a door closes softly, on a floor you thought was empty.','The library keeps its own time, and it is in no hurry to tell you what it is.'];
    const marginaliaAsides=['A faint pencil mark in the margin agrees with this sentence. You are not the first to underline it.','The corner of this page has been folded down before, by a hand not yours.','A pressed leaf, long flattened, marks a page you have already turned past.','Someone has written a single word in the margin, in ink too old to read.','A previous reader has corrected the author’s grammar, twice, in a tidy hand.','A faint ring on the page suggests a cup once rested exactly here.','Someone has drawn a small arrow beside this paragraph, pointing at nothing you can see.','The spine cracks open naturally to this page, worn soft by other thumbs.','A date is pencilled into the corner, decades before you were born.','Three words are underlined here, and nothing around them explains why.'];
    function showReaderAside(text){const el=$('#readerAside');if(!el)return;el.textContent=text;el.classList.add('show');clearTimeout(showReaderAside.timer);showReaderAside.timer=setTimeout(()=>el.classList.remove('show'),6000)}
    function flashReaderWeather(){const el=$('#readerFlicker');if(el&&weather==='STORM'){el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),220)}if(weather==='STORM')sound(50,1.1,'sine',.05);else if(weather==='RAIN')sound(90,.9,'sine',.025)}
    function scheduleReaderAside(){clearTimeout(readerAsideTimer);readerAsideTimer=setTimeout(maybeReaderAside,45000+Math.random()*35000)}
    function stopReaderAside(){clearTimeout(readerAsideTimer);readerAsideTimer=null;const el=$('#readerAside');if(el)el.classList.remove('show');const fl=$('#readerFlicker');if(fl)fl.classList.remove('flash')}
    function maybeReaderAside(){if(ui.reader.classList.contains('hidden'))return;if(!document.hidden){const book=selected?.userData?.book,options=['time'],inMainLibrary=player.pos.y>-.5&&Math.abs(player.pos.x)<57&&player.pos.z>-32&&player.pos.z<32;if(inMainLibrary)options.push('quill');if(book&&!marginaliaSeen.has(book.id))options.push('marginalia');if(weather==='STORM'||weather==='RAIN')options.push('weather','weather');const pick=options[Math.floor(Math.random()*options.length)];if(pick==='quill')showReaderAside(quillAsides[Math.floor(Math.random()*quillAsides.length)]);else if(pick==='time')showReaderAside(timeAsides[Math.floor(Math.random()*timeAsides.length)]);else if(pick==='marginalia'){if(book)marginaliaSeen.add(book.id);showReaderAside(marginaliaAsides[Math.floor(Math.random()*marginaliaAsides.length)])}else if(pick==='weather')flashReaderWeather()}scheduleReaderAside()}
